import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicInteger;

public class LatchBarrierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /** Runs runTogether on a daemon thread; null means it hung or threw. */
    static Integer guarded(int workers, Runnable job) {
        final Integer[] box = new Integer[1];
        Thread runner = new Thread(() -> {
            try {
                box[0] = Integer.valueOf(LatchBarrier.runTogether(workers, job));
            } catch (Throwable t) {
                box[0] = null;
            }
        });
        runner.setDaemon(true);
        runner.start();
        try {
            runner.join(4000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return runner.isAlive() ? null : box[0];
    }

    static Object describe(Integer value) {
        return value == null ? "no result (runTogether hung or threw)" : value;
    }

    public static void main(String[] args) {
        AtomicInteger counter = new AtomicInteger(0);
        check("four workers all report success", 4,
                describe(guarded(4, () -> counter.incrementAndGet())));
        check("four workers really ran the job four times", 4, counter.get());

        ConcurrentLinkedQueue<String> marks = new ConcurrentLinkedQueue<>();
        check("six workers", 6, describe(guarded(6, () -> marks.add("x"))));
        check("six marks were recorded", 6, marks.size());

        check("zero workers means zero successes", 0, describe(guarded(0, () -> counter.incrementAndGet())));
        check("zero workers never run the job", 4, counter.get());

        check("a job that always throws still returns 0", 0,
                describe(guarded(3, () -> {
                    throw new IllegalStateException("boom");
                })));

        AtomicInteger mixed = new AtomicInteger(0);
        check("only the non-throwing workers are counted", 2,
                describe(guarded(4, () -> {
                    if (mixed.incrementAndGet() <= 2) {
                        throw new IllegalStateException("boom");
                    }
                })));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

