import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * TASK: Coordinate a group of workers with two CountDownLatches.
 *
 * runTogether(workerCount, job) must:
 *   1. make a START GATE latch with a count of 1 and a DONE latch with a
 *      count of workerCount,
 *   2. start workerCount threads; each one first calls startGate.await(),
 *      then runs job.run(), then counts the DONE latch down,
 *   3. after all the threads are started, release them with startGate.countDown(),
 *   4. wait for every worker with doneLatch.await(),
 *   5. return how many workers finished job.run() WITHOUT throwing.
 *
 * TRICKY EDGE: if job.run() throws, that worker must STILL count the done
 * latch down -- put the countDown in a finally block. Otherwise await() never
 * returns and the whole program hangs.
 *
 * Example: runTogether(4, () -> counter.incrementAndGet()) -> 4
 *          runTogether(3, () -> { throw new RuntimeException(); }) -> 0 (and it returns!)
 *          runTogether(0, job) -> 0, and job never runs.
 */
public class LatchBarrier {

    public static int runTogether(int workerCount, Runnable job) throws InterruptedException {
        CountDownLatch startGate = new CountDownLatch(1);
        CountDownLatch doneLatch = new CountDownLatch(Math.max(workerCount, 0));
        AtomicInteger succeeded = new AtomicInteger(0);

        for (int i = 0; i < workerCount; i++) {
            Thread worker = new Thread(() -> {
                try {
                    startGate.await();
                    job.run();
                    succeeded.incrementAndGet();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } catch (RuntimeException e) {
                    // the worker failed, but it must still report that it is done
                } finally {
                    doneLatch.countDown();
                }
            });
            worker.start();
        }

        startGate.countDown();
        doneLatch.await();
        return succeeded.get();
    }
}
